/* singlePageNav 1.2.0 - jQuery 4 compatible build */
(function ($, window) {
  'use strict';
  var methods = {
    init: function (options, container) {
      this.options = $.extend({}, $.fn.singlePageNav.defaults, options);
      this.$container = $(container);
      this.$links = this.$container.find('a');
      if (this.options.filter !== '') this.$links = this.$links.filter(this.options.filter);
      this.$window = $(window);
      this.$htmlbody = $('html, body');
      this.$links.on('click.singlePageNav', this.handleClick.bind(this));
      this.didScroll = false;
      this.checkPosition();
      this.setTimer();
    },
    handleClick: function (event) {
      var link = event.currentTarget;
      var target = $(link.hash);
      event.preventDefault();
      if (!target.length) return;
      this.clearTimer();
      if (typeof this.options.beforeStart === 'function') this.options.beforeStart();
      this.setActiveLink(link.hash);
      this.scrollTo(target, function () {
        if (this.options.updateHash && history.pushState) history.pushState(null, null, link.hash);
        this.setTimer();
        if (typeof this.options.onComplete === 'function') this.options.onComplete();
      }.bind(this));
    },
    scrollTo: function (target, complete) {
      var completed = false;
      this.$htmlbody.stop().animate({ scrollTop: this.getCoords(target).top }, {
        duration: this.options.speed, easing: this.options.easing,
        complete: function () { if (typeof complete === 'function' && !completed) complete(); completed = true; }
      });
    },
    setTimer: function () {
      var self = this;
      this.$window.on('scroll.singlePageNav', function () { self.didScroll = true; });
      this.timer = setInterval(function () {
        if (self.didScroll) { self.didScroll = false; self.checkPosition(); }
      }, 250);
    },
    clearTimer: function () { clearInterval(this.timer); this.$window.off('scroll.singlePageNav'); this.didScroll = false; },
    checkPosition: function () { this.setActiveLink(this.getCurrentSection(this.$window.scrollTop())); },
    getCoords: function (target) { return { top: Math.round(target.offset().top) - this.options.offset }; },
    setActiveLink: function (hash) {
      var link = this.$container.find("a[href$='" + hash + "']");
      if (!link.hasClass(this.options.currentClass)) { this.$links.removeClass(this.options.currentClass); link.addClass(this.options.currentClass); }
    },
    getCurrentSection: function (scrollTop) {
      var section;
      for (var i = 0; i < this.$links.length; i++) {
        var hash = this.$links[i].hash;
        var target = $(hash);
        if (target.length && scrollTop >= this.getCoords(target).top - this.options.threshold) section = hash;
      }
      return section || this.$links[0].hash;
    }
  };
  $.fn.singlePageNav = function (options) { return this.each(function () { methods.init.call({}, options, this); }); };
  $.fn.singlePageNav.defaults = { offset: 0, threshold: 120, speed: 400, currentClass: 'current', easing: 'swing', updateHash: false, filter: '', onComplete: false, beforeStart: false };
}(jQuery, window));
